// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.concurrent.atomic.AtomicLong;

/**
 * Composes the current {@link LmdbNativeRegimeKey} from the store context's live signals and maintains the monotone
 * regime epoch. The epoch advances whenever the composed key changes (an index finished building, kernels warmed, data
 * mutated) and whenever the change detector demands it via {@link #forceEpochBump()}; probe cooldowns and dormant
 * states are scoped to an epoch, so a bump is what revives rejected arms for reconsideration. With a null context the
 * tracker degrades to the single {@link LmdbNativeRegimeKey#STEADY} regime and the epoch only moves on forced bumps.
 */
final class LmdbNativeRegimeTracker {

	private final LmdbNativeCostModelContext context;
	private final AtomicLong epoch = new AtomicLong();
	private volatile LmdbNativeRegimeKey cached = LmdbNativeRegimeKey.STEADY;

	LmdbNativeRegimeTracker(LmdbNativeCostModelContext context) {
		this.context = context;
	}

	LmdbNativeRegimeKey current() {
		if (context == null) {
			return LmdbNativeRegimeKey.STEADY;
		}
		LmdbNativeRegimeKey composed = compose();
		LmdbNativeRegimeKey previous = cached;
		if (!composed.equals(previous)) {
			synchronized (this) {
				if (!composed.equals(cached)) {
					cached = composed;
					epoch.incrementAndGet();
				}
			}
		}
		return composed;
	}

	long epoch() {
		return epoch.get();
	}

	void forceEpochBump() {
		epoch.incrementAndGet();
	}

	private LmdbNativeRegimeKey compose() {
		boolean kernelReady = LmdbNativeJaninoCodegen.kernelsReady();
		String phaseName = context.maintenancePhase().get();
		LmdbNativeRegimeKey.Phase phase = mapPhase(phaseName, kernelReady);
		return new LmdbNativeRegimeKey(phase, context.adjacencyEpoch().getAsLong(), kernelReady,
				context.dataGeneration().getAsLong());
	}

	/**
	 * Maintenance-state names map onto the three phases: build-in-progress states are BUILDING; degraded or unsettled
	 * states are TRANSITIONAL_COLD; ACTIVE, DISABLED (no adjacency store at all) and EMPTY (a store that never triggers
	 * an adjacency build — a legitimate steady state) are WARM_STABLE once kernels are ready. Unknown names
	 * conservatively land in TRANSITIONAL_COLD so a future maintenance state cannot silently pollute steady-state
	 * evidence.
	 */
	static LmdbNativeRegimeKey.Phase mapPhase(String maintenanceState, boolean kernelReady) {
		switch (maintenanceState) {
		case "BUILDING":
		case "CATCHING_UP":
		case "QUIESCING_FOR_REBUILD":
			return LmdbNativeRegimeKey.Phase.BUILDING;
		case "ACTIVE":
		case "DISABLED":
		case "EMPTY":
			return kernelReady ? LmdbNativeRegimeKey.Phase.WARM_STABLE : LmdbNativeRegimeKey.Phase.TRANSITIONAL_COLD;
		default:
			return LmdbNativeRegimeKey.Phase.TRANSITIONAL_COLD;
		}
	}
}
